127	/**
128	 * Server-side page guard. Redirects to /login if signed out, or back to the
129	 * overview if the (staff) user's role can't reach this area. Returns the real
130	 * signed-in user (impersonation is refused elsewhere in the admin layout).
131	 */
132	export async function requireArea(area: Area): Promise<User> {
133	  const user = await realUser();
134	  if (!user) redirect("/login");
135	  if (!isStaff(user.role)) redirect("/dashboard");
136	  if (!canAccess(user.role, area)) redirect("/admin");
