128	/**
129	 * A TypeScript parameter type is a compile-time comment on a network endpoint.
130	 *
131	 * Every export of this file is POST-able with any JSON the caller likes, so the
132	 * `"OPEN" | "CLOSED"` annotations below constrained the components and nothing
133	 * else. `TicketStatus` also contains ANSWERED and CUSTOMER_REPLY — both writable
134	 * here — so a customer could stamp their own ticket ANSWERED and drop it out of
135	 * the support queue's "needs a reply" view without anyone having replied. Values
136	 * outside the enum reached Prisma and threw, which surfaces as a server error
137	 * page rather than a message. Both are fixed by validating at the boundary.
138	 */
139	const TICKET_STATUS_CHOICES = ["OPEN", "CLOSED"] as const;
140	const TICKET_PRIORITY_CHOICES = ["LOW", "NORMAL", "HIGH", "URGENT"] as const;
141	
142	export async function setTicketStatus(ticketId: string, status: "OPEN" | "CLOSED") {
143	  const user = await requireTicketActor();
144	  if (!TICKET_STATUS_CHOICES.includes(status as (typeof TICKET_STATUS_CHOICES)[number])) {
145	    throw new Error("A ticket can only be reopened or closed from here.");
146	  }
147	  const ticket = await db.ticket.findUnique({ where: { id: ticketId } });
148	  if (!ticket) throw new Error("Not found");
149	  if (ticket.userId !== user.id && !user.isSupportStaff) throw new Error("Forbidden");
150	  await db.ticket.update({ where: { id: ticketId }, data: { status } });
151	  revalidatePath(`/dashboard/support`);
152	  revalidatePath(`/dashboard/support/${ticketId}`);
153	  revalidatePath(`/admin/support`);
154	  revalidatePath(`/admin/support/${ticketId}`);
155	}
156	
157	export async function setTicketPriority(ticketId: string, priority: "LOW" | "NORMAL" | "HIGH" | "URGENT") {
158	  const user = await requireTicketActor();
159	  // Triage is a staff-only judgement — a customer must not be able to promote
160	  // their own ticket to URGENT — but it IS the support desk's job.
161	  if (!user.isSupportStaff) throw new Error("Forbidden");
162	  if (!TICKET_PRIORITY_CHOICES.includes(priority as (typeof TICKET_PRIORITY_CHOICES)[number])) {
163	    throw new Error("Priority must be one of: LOW, NORMAL, HIGH, URGENT.");
164	  }
165	  await db.ticket.update({ where: { id: ticketId }, data: { priority } });
166	  revalidatePath(`/admin/support`);
167	  revalidatePath(`/admin/support/${ticketId}`);
168	}
