1	"use server";
2	
3	import { revalidatePath } from "next/cache";
4	import { db } from "./db";
5	import { requireUser } from "./auth";
6	import { checkRateLimit } from "./rate-limit";
7	import { canAdministerOrg, signInviteToken, verifyInviteToken, INVITE_TTL_HOURS } from "./team-guard";
8	
9	/**
10	 * Teams / Organizations — shared-account server actions.
11	 *
12	 * An Organization has one owner (User "OrgOwner") plus a set of Memberships.
13	 * Every actor is verified to hold a Membership of the required role in the
14	 * target org before any mutation runs, so a hand-crafted request can't touch
15	 * an org the caller doesn't belong to.
16	 *
17	 * WHAT A MEMBERSHIP ACTUALLY GRANTS (be precise — this used to be overstated):
18	 * visibility of the org roster, and, for OWNER/ADMIN, the right to invite,
19	 * re-role and remove members. It grants NOTHING ELSE. Servers, domains,
20	 * volumes, game servers, billing and invoices all remain scoped to the account
21	 * that owns them; no loader or action anywhere joins Membership to a resource.
22	 * The per-member "dashboard areas" control that used to sit on this page has
23	 * been removed rather than left in place: `Membership.areas` was written, echoed
24	 * back as saved, and read by nothing, so an owner who restricted a member to
25	 * Invoices was shown a restriction that did not exist. See lib/team-guard.ts for
26	 * why enforcing it for real is out of this change's reach, and the note rendered
27	 * in components/customer/TeamManager.tsx for what the customer is now told.
28	 *
29	 * CONSENT: `inviteMember` emails an invitation; only `acceptInvite`, run by the
30	 * invitee, creates a Membership. Nothing here can add a person to an org they
31	 * did not agree to join — see lib/team-guard.ts for the full rationale (it is
32	 * what fed the 2FA oracle, QA-PRELAUNCH P0-2).
33	 *
34	 * STILL OUT OF SCOPE: shared billing (org wallet / invoices) and members
35	 * inheriting access to shared servers. Deliberately absent, not half-built.
36	 */
37	
38	const ROLES = ["OWNER", "ADMIN", "MEMBER", "BILLING"] as const;
39	type OrgRole = (typeof ROLES)[number];
40	
41	function isRole(v: string): v is OrgRole {
42	  return (ROLES as readonly string[]).includes(v);
43	}
44	
45	/** Load the actor's membership in an org, or null if they aren't a member. */
46	async function actorMembership(orgId: string, userId: string) {
47	  if (!orgId) return null;
48	  return db.membership.findUnique({
49	    where: { orgId_userId: { orgId, userId } },
50	  });
51	}
52	
53	/**
54	 * Create an organization owned by the current user, plus an OWNER membership
55	 * for the creator. Consumed via `useActionState`.
56	 */
57	export async function createOrg(
58	  _prev: unknown,
59	  formData: FormData,
60	): Promise<{ error?: string; ok?: boolean }> {
61	  const user = await requireUser();
62	  const name = String(formData.get("name") ?? "").trim();
63	  if (name.length < 2 || name.length > 60) {
64	    return { error: "Organization name must be 2–60 characters." };
65	  }
66	
67	  await db.organization.create({
68	    data: {
69	      name,
70	      ownerId: user.id,
71	      members: {
72	        create: { userId: user.id, role: "OWNER" },
73	      },
74	    },
75	  });
76	
77	  await db.auditLog.create({
78	    data: { userId: user.id, action: "org.created", detail: name },
79	  });
80	  revalidatePath("/dashboard/team");
81	  return { ok: true };
82	}
83	
84	/**
85	 * Email an invitation. Only OWNER/ADMIN of the org may invite. **No Membership
86	 * is created here** — the invitee creates it themselves via `acceptInvite`.
87	 *
88	 * Deliberately does NOT look the email up in the User table. The old version
89	 * did, and that single query produced two leaks from one action any signed-in
90	 * customer can call: it answered "does an account exist with this address?"
91	 * (enumeration oracle), and on a hit it created a Membership whose row then
92	 * exposed the invitee's internal `userId` on the team page — the input the
93	 * unauthenticated 2FA oracle needed (QA-PRELAUNCH P0-2). We send the mail and
94	 * learn nothing: the same response comes back whether or not the address has an
95	 * account, and the sender finds out only if the person chooses to accept.
96	 */
97	export async function inviteMember(
98	  orgId: string,
99	  email: string,
100	  role: string,
101	): Promise<{ error?: string; ok?: boolean; message?: string }> {
102	  const user = await requireUser();
103	  const invitedEmail = String(email ?? "").trim().toLowerCase();
104	  if (!invitedEmail || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(invitedEmail)) {
105	    return { error: "Enter a valid email address." };
106	  }
107	  const wantRole = String(role ?? "MEMBER").toUpperCase();
108	  if (!isRole(wantRole) || wantRole === "OWNER") {
109	    // OWNER is assigned only at creation / ownership transfer, never via invite.
110	    return { error: "Choose a role of ADMIN, MEMBER or BILLING." };
111	  }
112	
113	  const actor = await actorMembership(orgId, user.id);
114	  if (!actor || !canAdministerOrg(actor.role)) {
115	    return { error: "You don't have permission to invite members to this organization." };
116	  }
117	
118	  const org = await db.organization.findUnique({ where: { id: orgId }, select: { name: true } });
119	  if (!org) return { error: "Organization not found." };
120	
121	  if (invitedEmail === user.email.toLowerCase()) {
122	    return { error: "You're already a member of this organization." };
123	  }
124	
125	  // Narrow lookup, and the ONLY one allowed here: does this address already have
126	  // a Membership *in this org*? It answers nothing the caller can't already see —
127	  // they administer this org, so the roster and its addresses are theirs to read
128	  // (app/dashboard/team/page.tsx) — and it returns null for a non-member whether
129	  // or not that address has an account, so it is not the enumeration oracle the
130	  // old `db.user.findUnique` was. Saves emailing an invitation that would be a
131	  // no-op on accept.
132	  const alreadyIn = await db.membership.findFirst({
133	    where: { orgId, user: { email: invitedEmail } },
134	    select: { id: true },
135	  });
136	  if (alreadyIn) {
137	    return { error: "That person is already a member of this organization." };
138	  }
139	
140	  // Throttle per inviter. This action sends Nxeon-branded mail to an arbitrary
141	  // address chosen by the caller, so without a cap it is a spam relay and a way
142	  // to bury someone in invitations. Same shape as the login / password-reset
143	  // throttles (lib/rate-limit.ts).
144	  const rl = checkRateLimit(`org-invite:${user.id}`, { max: 10, windowMs: 60 * 60 * 1000 });
145	  if (!rl.ok) {
146	    return {
147	      error: `Too many invitations sent recently. Try again in ${Math.ceil(rl.retryAfterSec / 60)} minute(s).`,
148	    };
149	  }
150	
151	  const token = await signInviteToken({
152	    orgId,
153	    email: invitedEmail,
154	    role: wantRole,
155	    invitedBy: user.id,
156	  });
157	  const base = (process.env.APP_URL ?? "https://nxeon.cloud").replace(/\/$/, "");
158	  const acceptUrl = `${base}/dashboard/team/accept?token=${encodeURIComponent(token)}`;
159	
160	  const { sendMail, emails } = await import("./mailer");
161	  const tpl = emails.teamInvite({
162	    inviterName: user.name,
163	    teamName: org.name,
164	    acceptUrl,
165	  });
166	  // `template` is passed so the send is categorised in the admin EmailLog viewer
167	  // (same shape as worker/billing.ts:182). No `userId`: we deliberately never
168	  // resolved the address to an account, so there is no id to attribute it to.
169	  const sent = await sendMail({
170	    to: invitedEmail,
171	    subject: tpl.subject,
172	    html: tpl.html,
173	    template: tpl.template,
174	  });
175	  if (!sent) {
176	    // Report the failure instead of claiming the invitation went out. `sendMail`
177	    // returns false (and logs to EmailLog) when SMTP is unconfigured or the send
178	    // throws; a cheerful "Invitation sent." over a dropped email is exactly the
179	    // confidently-wrong surface this codebase keeps getting bitten by.
180	    return { error: "We couldn't send that invitation email. Check mail settings and try again." };
181	  }
182	
183	  await db.auditLog.create({
184	    data: {
185	      userId: user.id,
186	      action: "org.invite_sent",
187	      detail: `${invitedEmail} → ${wantRole}`,
188	    },
189	  });
190	  return {
191	    ok: true,
192	    message: `Invitation emailed to ${invitedEmail}. They join the organization when they accept it — the link expires in ${INVITE_TTL_HOURS} hours.`,
193	  };
194	}
195	
196	/**
197	 * Accept an invitation. This is the ONLY path that creates a Membership for
198	 * someone other than an org's creator, and it runs as the invitee — clicking
199	 * Accept while signed in as the invited address *is* the consent.
200	 *
201	 * Must be triggered by a deliberate click, never on page load: a mutation that
202	 * fires when the emailed URL is merely opened (or prefetched) would join people
203	 * to organizations without their agreement all over again.
204	 *
205	 * Re-checks at redemption time, because the token carries no server-side state:
206	 * the org still exists, the inviter still administers it, the role is still
207	 * sane, and the token's address matches the signed-in account.
208	 */
209	export async function acceptInvite(
210	  token: string,
211	): Promise<{ error?: string; ok?: boolean; orgName?: string; alreadyMember?: boolean }> {
212	  const user = await requireUser();
213	
214	  const claims = await verifyInviteToken(String(token ?? ""));
215	  if (!claims) {
216	    return {
217	      error: "This invitation link is invalid or has expired. Ask the organization owner to send a new one.",
218	    };
219	  }
220	
221	  // Bound to one address, so a forwarded link can't be redeemed by the recipient.
222	  if (claims.email !== user.email.trim().toLowerCase()) {
223	    return {
224	      error: "This invitation was sent to a different email address. Sign in as that account to accept it.",
225	    };
226	  }
227	
228	  if (!isRole(claims.role) || claims.role === "OWNER") {
229	    return { error: "This invitation carries an invalid role and can't be accepted." };
230	  }
231	
232	  const org = await db.organization.findUnique({
233	    where: { id: claims.orgId },
234	    select: { id: true, name: true },
235	  });
236	  if (!org) return { error: "That organization no longer exists." };
237	
238	  // Revocation, given there is no invitation row to delete: an outstanding
239	  // invitation dies the moment its sender loses the right to have sent it.
240	  const inviter = await actorMembership(org.id, claims.invitedBy);
241	  if (!inviter || !canAdministerOrg(inviter.role)) {
242	    return {
243	      error: "Whoever invited you no longer administers this organization, so the invitation is no longer valid.",
244	    };
245	  }
246	
247	  const existing = await actorMembership(org.id, user.id);
248	  if (existing) {
249	    return { ok: true, orgName: org.name, alreadyMember: true };
250	  }
251	
252	  await db.membership.create({
253	    data: { orgId: org.id, userId: user.id, role: claims.role },
254	  });
255	  await db.auditLog.create({
256	    data: {
257	      userId: user.id,
258	      action: "org.invite_accepted",
259	      detail: `${org.name} → ${claims.role}`,
260	    },
261	  });
262	  revalidatePath("/dashboard/team");
263	  return { ok: true, orgName: org.name };
264	}
265	
266	/**
267	 * Change a member's role. Only OWNER/ADMIN act. The owner's own membership is
268	 * pinned to OWNER and cannot be downgraded here.
269	 *
270	 * Takes a `membershipId`, not a `userId`: the client is never sent co-members'
271	 * user ids any more (see app/dashboard/team/page.tsx), so it has none to send
272	 * back. The org is derived from the membership rather than trusted from the
273	 * caller, which also removes the chance of a mismatched (orgId, userId) pair.
274	 */
275	export async function updateMemberRole(
276	  membershipId: string,
277	  role: string,
278	): Promise<{ error?: string; ok?: boolean }> {
279	  const user = await requireUser();
280	  const wantRole = String(role ?? "").toUpperCase();
281	  if (!isRole(wantRole) || wantRole === "OWNER") {
282	    return { error: "Pick a role of ADMIN, MEMBER or BILLING." };
283	  }
284	
285	  const target = await db.membership.findUnique({ where: { id: String(membershipId ?? "") } });
286	  if (!target) return { error: "That person isn't a member of this organization." };
287	
288	  const actor = await actorMembership(target.orgId, user.id);
289	  if (!actor || !canAdministerOrg(actor.role)) {
290	    return { error: "You don't have permission to change roles in this organization." };
291	  }
292	
293	  const org = await db.organization.findUnique({
294	    where: { id: target.orgId },
295	    select: { ownerId: true },
296	  });
297	  if (!org) return { error: "Organization not found." };
298	  if (target.userId === org.ownerId || target.role === "OWNER") {
299	    return { error: "The organization owner's role can't be changed." };
300	  }
301	
302	  await db.membership.update({
303	    where: { id: target.id },
304	    data: { role: wantRole },
305	  });
306	  await db.auditLog.create({
307	    data: {
308	      userId: user.id,
309	      action: "org.member_role_changed",
310	      detail: `${target.userId} → ${wantRole}`,
311	    },
312	  });
313	  revalidatePath("/dashboard/team");
314	  return { ok: true };
315	}
316	
317	/**
318	 * Remove a member. Only OWNER/ADMIN act; the owner can never be removed.
319	 * Keyed by `membershipId` for the same reason as `updateMemberRole`.
320	 */
321	export async function removeMember(
322	  membershipId: string,
323	): Promise<{ error?: string; ok?: boolean }> {
324	  const user = await requireUser();
325	
326	  const target = await db.membership.findUnique({ where: { id: String(membershipId ?? "") } });
327	  if (!target) return { error: "That person isn't a member of this organization." };
328	
329	  const actor = await actorMembership(target.orgId, user.id);
330	  if (!actor || !canAdministerOrg(actor.role)) {
331	    return { error: "You don't have permission to remove members from this organization." };
332	  }
333	
334	  const org = await db.organization.findUnique({
335	    where: { id: target.orgId },
336	    select: { ownerId: true },
337	  });
338	  if (!org) return { error: "Organization not found." };
339	  if (target.userId === org.ownerId || target.role === "OWNER") {
340	    return { error: "The organization owner can't be removed." };
341	  }
342	
343	  await db.membership.delete({ where: { id: target.id } });
344	  await db.auditLog.create({
345	    data: { userId: user.id, action: "org.member_removed", detail: target.userId },
346	  });
347	  revalidatePath("/dashboard/team");
348	  return { ok: true };
349	}
