232	/** Fetch one full message: parsed + SANITISED html, attachments listed, marked \Seen. */
233	export async function getMessage(folder: string, uid: number, mailboxAddress?: string): Promise<MessageFull> {
234	  const { cred } = await resolveMailbox(mailboxAddress);
235	
236	  return withMailbox(cred, folder, async (client) => {
237	    const msg = await client.fetchOne(
238	      String(uid),
239	      { uid: true, source: true, flags: true, envelope: true, internalDate: true },
240	      { uid: true },
241	    );
242	    if (!msg || !msg.source) throw new Error("Message not found.");
243	
244	    const parsed = await parseMessage(msg.source);
245	    const flags = readFlags(msg.flags);
246	    const env = msg.envelope;
247	
248	    const attachments = (parsed.attachments || [])
249	      .filter((a) => a.related !== true) // skip inline/embedded (cid) images
250	      .map((a, i) => ({
251	        id: `${uid}:${a.partId ?? String(i + 1)}`,
252	        filename: a.filename || `attachment-${i + 1}`,
253	        mime: a.contentType || "application/octet-stream",
254	        sizeBytes: a.size ?? 0,
255	      }));
256	
257	    const full: MessageFull = {
258	      uid,
259	      folder,
260	      from: toMailAddress(env?.from?.[0]),
261	      to: toMailAddresses(env?.to),
262	      cc: toMailAddresses(env?.cc),
263	      subject: env?.subject || parsed.subject || "(no subject)",
264	      preview: previewText(parsed.text || (typeof parsed.html === "string" ? parsed.html : "")),
265	      date: isoDate(msg),
266	      seen: true, // becomes read as a side effect of opening
267	      flagged: flags.flagged,
268	      answered: flags.answered,
269	      hasAttachments: attachments.length > 0,
270	      html: typeof parsed.html === "string" ? safeHtml(parsed.html) : null,
271	      text: parsed.text ?? null,
272	      attachments,
273	    };
274	
275	    // Mark read (mailbox opened read-write). Best effort — never fail the read.
276	    try {
277	      await client.messageFlagsAdd(String(uid), ["\\Seen"], { uid: true });
278	    } catch {
279	      /* ignore */
280	    }
281	
282	    return full;
283	  });
284	}
