577	/** Delete a message: move to Trash, or permanently expunge if already in Trash. */
578	export async function deleteMessage(folder: string, uid: number, mailboxAddress?: string): Promise<void> {
579	  const { user, cred } = await resolveMailbox(mailboxAddress);
580	  enforceRateLimit(`mail:delete:${user.id}`, { max: 120, windowMs: 60 * 1000 });
581	
582	  await withImap(cred, async (client) => {
583	    // Determine the Trash folder path.
584	    let trashPath = "Trash";
585	    try {
586	      const list = await client.list();
587	      const trash = list.find((f) => folderRole(f.path, f.specialUse) === "trash");
588	      if (trash) trashPath = trash.path;
589	    } catch {
590	      /* fall back to "Trash" */
591	    }
592	
593	    const inTrash = folderRole(folder) === "trash" || folder === trashPath;
594	    const lock = await client.getMailboxLock(folder);
595	    try {
596	      if (inTrash) {
597	        await client.messageDelete(String(uid), { uid: true });
598	      } else {
599	        await client.messageMove(String(uid), trashPath, { uid: true });
600	      }
601	    } finally {
602	      lock.release();
603	    }
604	  });
605	}
