94	/** Parse a `YYYY-MM-DD` string into a UTC Date, or null when blank/invalid. */
95	function fromDateInput(s: string | null | undefined): Date | null {
96	  const v = (s ?? "").trim();
97	  if (!v) return null;
98	  const d = new Date(`${v}T00:00:00.000Z`);
99	  return Number.isNaN(d.getTime()) ? null : d;
