73	/**
74	 * Business Email — mailbox hosting per registered domain.
75	 *
76	 * An `EmailPlan` is a pricing tier (N mailboxes, GB/mailbox, price, term). A
77	 * customer subscribes one of their own domains to a tier (`EmailSubscription`),
78	 * which debits the wallet, then manages individual `Mailbox` rows under it.
79	 *
80	 * Mail delivery runs through a self-hosted Mailcow server, reached via lib/mailcow.ts
81	 * (config from MAILCOW_API_URL / MAILCOW_API_KEY). Creating a Mailbox row records
82	 * intent (status PROVISIONING); we then attempt to provision the real mailbox on
83	 * Mailcow and flip the row to ACTIVE, or FAILED if the call errors. All Mailcow
84	 * calls are additive and failure-tolerant — a Mailcow outage never breaks the
85	 * order flow; the row persists and can be retried via retryMailboxProvision.
86	 *
87	 * This module owns:
88	 *   - orderEmailHosting (customer subscribe)
89	 *   - addMailbox / removeMailbox / retryMailboxProvision (customer mailbox management)
90	 *   - adminSaveEmailPlan / adminToggleEmailPlan / adminDeleteEmailPlan (CRUD)
91	 */
92	
93	type Result = { error?: string; ok?: boolean; warning?: string };
94	
95	/**
96	 * Provision (or re-provision) a mailbox on Mailcow. Never throws — records the
97	 * outcome on the Mailbox row (status ACTIVE on success, FAILED on error) and
98	 * returns it. When Mailcow isn't configured the row is left PROVISIONING so it
99	 * can be picked up once the integration is wired.
100	 */
101	async function provisionMailboxOnMailcow(mailbox: {
102	  id: string;
103	  address: string;
104	  quotaMB: number | null;
105	  subscription: { domainName: string };
106	}): Promise<"ACTIVE" | "FAILED" | "PROVISIONING"> {
107	  if (!mailcowConfigured()) return "PROVISIONING";
108	
109	  const [localPart] = mailbox.address.split("@");
110	  const domain = mailbox.subscription.domainName;
111	  const quotaMB = mailbox.quotaMB ?? 1024;
112	
113	  try {
114	    // Ensure the mail domain exists before adding the mailbox.
115	    if (!(await mcDomainExists(domain))) {
116	      // A concurrent create or pre-existing domain can still error here; ignore
117	      // and let the mailbox add be the real signal.
118	      await mcCreateDomain(domain).catch(() => {});
119	    }
120	
121	    const password = randomBytes(18).toString("base64url");
122	    await mcCreateMailbox({
123	      localPart,
124	      domain,
125	      name: mailbox.address,
126	      password,
127	      quotaMB,
128	    });
129	
130	    await db.mailbox.update({
131	      where: { id: mailbox.id },
132	      data: { status: "ACTIVE", passwordEnc: encryptSecret(password) },
133	    });
134	    return "ACTIVE";
135	  } catch (e) {
136	    await db.mailbox
137	      .update({ where: { id: mailbox.id }, data: { status: "FAILED" } })
138	      .catch(() => {});
139	    console.warn(`[mailcow] provisioning ${mailbox.address} failed:`, e);
140	    return "FAILED";
141	  }
142	}
