508	/**
509	 * Verify that an EXTERNAL domain's owner has published our verification record.
510	 * Resolves the `_nxeon-verify` TXT via DNS and confirms it contains
511	 * `nxeon-verify=<verifyToken>`; the MX pointing at the mail host is accepted as
512	 * corroboration. The result is derived entirely server-side from live DNS —
513	 * client input never decides the outcome. Rate-limited per user + subscription.
514	 */
515	export async function verifyEmailDomain(subscriptionId: string): Promise<Result> {
516	  const user = await requireUser();
517	
518	  const sub = await db.emailSubscription.findUnique({ where: { id: subscriptionId } });
519	  if (!sub) return { error: "Subscription not found." };
520	  if (sub.userId !== user.id) return { error: "Not your subscription." };
521	  if (!sub.external) return { error: "This domain is managed by Nxeon — no verification needed." };
522	  if (sub.verified) return { ok: true };
523	  if (!sub.verifyToken) return { error: "No verification token on this subscription." };
524	
525	  const rl = checkRateLimit(`email-verify:${user.id}:${sub.id}`, {
526	    max: 6,
527	    windowMs: 60_000,
528	  });
529	  if (!rl.ok) {
530	    return { error: `Too many verification attempts. Try again in ${rl.retryAfterSec}s.` };
531	  }
532	
533	  const domain = sub.domainName;
534	  const expected = `nxeon-verify=${sub.verifyToken}`;
535	
536	  // Primary signal: the verification TXT record must contain our exact token.
537	  let tokenFound = false;
538	  try {
539	    const txt = await resolveTxt(`_nxeon-verify.${domain}`);
540	    // Each record may be split into multiple strings — join per-record chunks.
541	    tokenFound = txt.some((chunks) => chunks.join("").trim() === expected);
542	  } catch {
543	    tokenFound = false;
544	  }
545	
546	  // Corroboration: MX pointing at the mail host (does not substitute for the token).
547	  let mxOk = false;
548	  try {
549	    const mx = await resolveMx(domain);
550	    mxOk = mx.some((r) => r.exchange.replace(/\.$/, "").toLowerCase() === MAIL_HOST);
551	  } catch {
552	    mxOk = false;
553	  }
554	
555	  if (!tokenFound) {
556	    return {
557	      error: mxOk
558	        ? "MX is set, but the _nxeon-verify TXT record isn't visible yet. DNS can take a few minutes to propagate."
559	        : "Verification record not found yet. Add the _nxeon-verify TXT record and try again (DNS can take a few minutes).",
560	    };
561	  }
562	
563	  await db.emailSubscription.update({
564	    where: { id: sub.id },
565	    data: { verified: true, verifiedAt: new Date() },
566	  });
567	
568	  await db.auditLog.create({
569	    data: {
570	      userId: user.id,
571	      action: "emailhosting.verify",
572	      detail: `${domain}${mxOk ? " (MX + TXT)" : " (TXT)"}`,
573	    },
574	  });
575	  revalidatePath("/dashboard/email");
576	  return { ok: true };
577	}
