581	/**
582	 * Run the SPF / DKIM / DMARC / MX self-check for a subscription the caller owns.
583	 *
584	 * WHY: "my mail goes to spam" was previously undiagnosable from inside the
585	 * product — the platform owner hit exactly this and had to reach for an external
586	 * tool. This returns pass/fail per record with the value actually observed beside
587	 * the expected one, so the customer can see which DNS row is wrong.
588	 *
589	 * Two correctness rules this depends on:
590	 *   - DNS is read from the ZONE'S AUTHORITATIVE NAMESERVERS, never the system
591	 *     resolver (see lib/mail/deliverability.ts — this host's `hosts: files …`
592	 *     nsswitch order can answer from /etc/hosts and looks like a real lookup).
593	 *   - DKIM is compared against Mailcow's LIVE key, not `sub.dkimRecord`, which is
594	 *     a write-once cache that can outlive a key rotation.
595	 *
596	 * Rate-limited: each run makes several outbound DNS queries plus one Mailcow call.
597	 */
598	export async function checkEmailDeliverability(
599	  subscriptionId: string,
600	): Promise<{ error?: string; report?: DeliverabilityReport }> {
601	  const user = await requireUser();
602	
603	  const sub = await db.emailSubscription.findUnique({ where: { id: subscriptionId } });
604	  if (!sub) return { error: "Subscription not found." };
605	  if (sub.userId !== user.id) return { error: "Not your subscription." };
606	  // A cancelled subscription's domain may since have been taken by another
607	  // customer (the duplicate guard in orderEmailHosting only excludes CANCELLED
608	  // rows), so the old owner must not keep a live probe pointed at it.
609	  if (sub.status === "CANCELLED") return { error: "This subscription is cancelled." };
610	
611	  // NOTE on domain verification: this check deliberately does NOT require
612	  // `sub.verified`, unlike every action that changes mail routing. It only READS
613	  // public DNS and Mailcow's public DKIM key, changes nothing, and an unverified
614	  // domain is precisely the case a customer needs it for — gating it would hide
615	  // the diagnosis exactly when the records are wrong. Ownership of the
616	  // subscription is still required so the panel can't be used to scan arbitrary
617	  // domains through our server.
618	  const rl = checkRateLimit(`email-deliverability:${user.id}`, { max: 10, windowMs: 60_000 });
619	  if (!rl.ok) return { error: `Too many checks. Try again in ${rl.retryAfterSec}s.` };
620	
621	  // LIVE key only. A failure here degrades the DKIM row to "unknown" rather than
622	  // silently comparing against a cached value that may no longer sign anything.
623	  let dkim: { selector: string; txt: string } | null = null;
624	  if (mailcowConfigured()) {
625	    try {
626	      const live = await mcGetDkimDetails(sub.domainName);
627	      if (live) dkim = { selector: live.selector, txt: live.txt };
628	    } catch (e) {
629	      console.warn(`[mailcow] live dkim lookup for ${sub.domainName} failed:`, e);
630	    }
631	  }
632	
633	  try {
634	    const report = await checkDeliverability({
635	      domain: sub.domainName,
636	      mailHost: MAIL_HOST,
637	      spfInclude: SPF_INCLUDE,
638	      spfExpected: SPF_VALUE,
639	      dmarcExpected: DMARC_VALUE,
640	      dkim,
641	    });
642	    return { report };
643	  } catch (e) {
644	    console.warn(`[deliverability] check for ${sub.domainName} failed:`, e);
645	    return { error: "Couldn't complete the DNS check right now. Please try again in a moment." };
646	  }
647	}
