766	/** Remove a mailbox the caller owns (via its subscription). */
767	export async function removeMailbox(mailboxId: string): Promise<Result> {
768	  const user = await requireUser();
769	
770	  const mailbox = await db.mailbox.findUnique({
771	    where: { id: mailboxId },
772	    include: { subscription: true },
773	  });
774	  if (!mailbox) return { error: "Mailbox not found." };
775	  if (mailbox.subscription.userId !== user.id) return { error: "Not your mailbox." };
776	
777	  // Delete on Mailcow BEFORE dropping our row — and distinguish the two failure
778	  // modes, because they demand opposite actions:
779	  //
780	  //   - Mailcow REFUSED (reachable, returned an error): the mail server and our
781	  //     database disagree about this mailbox. Deleting our row here would leave a
782	  //     LIVE mailbox still receiving the customer's mail with no record of it in
783	  //     the product — silent data loss. Surface the error and keep the row.
784	  //   - Mailcow UNREACHABLE (transport failure): the server may just be down.
785	  //     Blocking removal forever on an outage is wrong, so we drop our row and
786	  //     tell the customer the mailbox itself may still exist and to retry once
787	  //     mail service is back.
788	  //
789	  // The previous `.catch(() => {})` collapsed both into "deleted, ok:true" — the
790	  // worse answer in every case.
791	  let mailcowUnreachable = false;
792	  if (mailcowConfigured()) {
793	    try {
794	      await mcDeleteMailbox(mailbox.address);
795	    } catch (e) {
796	      if (isMailcowUnreachable(e)) {
797	        mailcowUnreachable = true;
798	        console.warn(`[mailcow] delete ${mailbox.address}: unreachable, removing local record anyway:`, e);
799	      } else {
800	        console.error(`[mailcow] delete ${mailbox.address} REFUSED:`, e);
801	        return {
802	          error:
803	            "The mail server wouldn't remove this mailbox, so we've left it in place rather than lose your mail. Please try again in a moment, or contact support if it keeps happening.",
804	        };
805	      }
806	    }
807	  }
808	
809	  await db.mailbox.delete({ where: { id: mailbox.id } });
810	
811	  await db.auditLog.create({
812	    data: {
813	      userId: user.id,
814	      action: "mailbox.remove",
815	      detail: mailcowUnreachable ? `${mailbox.address} (mailcow unreachable — server-side delete not confirmed)` : mailbox.address,
816	    },
817	  });
818	  revalidatePath("/dashboard/email");
819	  return mailcowUnreachable
820	    ? {
821	        ok: true,
822	        warning:
823	          "Removed from your account. The mail server was unreachable, so the mailbox itself may still exist — it will be cleared when mail service is back, or contact support if messages keep arriving.",
824	      }
825	    : { ok: true };
826	}
