1	"use server";
2	
3	import { revalidatePath } from "next/cache";
4	import { randomBytes } from "node:crypto";
5	import { db } from "./db";
6	import { requireUser } from "./auth";
7	import { hashToken, TOKEN_PREFIX } from "./api-auth";
8	
9	/**
10	 * Customer API-token server actions.
11	 *
12	 * Tokens are `nxe_<prefix>_<random>`. Only the sha256 hash + short prefix are
13	 * persisted; the full token is shown exactly once at creation time.
14	 */
15	
16	const VALID_SCOPES = ["read", "write"] as const;
17	
18	/** Create a token. Returns the plaintext ONCE — it is never retrievable again. */
19	export async function createApiToken(
20	  prev: unknown,
21	  formData: FormData,
22	): Promise<{ error?: string; token?: string; name?: string }> {
23	  const user = await requireUser();
24	  const name = String(formData.get("name") ?? "").trim();
25	  if (name.length < 1 || name.length > 60) return { error: "Token name: 1–60 characters." };
26	
27	  const scopesRaw = formData.getAll("scopes").map(String);
28	  const scopes = scopesRaw.filter((s): s is (typeof VALID_SCOPES)[number] =>
29	    (VALID_SCOPES as readonly string[]).includes(s),
30	  );
31	  if (scopes.length === 0) scopes.push("read");
32	
33	  // Optional expiry in days.
34	  const expiresDays = Number(formData.get("expiresDays") ?? "");
35	  let expiresAt: Date | null = null;
36	  if (Number.isFinite(expiresDays) && expiresDays > 0) {
37	    expiresAt = new Date(Date.now() + expiresDays * 24 * 60 * 60 * 1000);
38	  }
39	
40	  const prefix = randomBytes(4).toString("hex"); // 8-char public prefix
41	  const secret = randomBytes(24).toString("base64url");
42	  const fullToken = `${TOKEN_PREFIX}_${prefix}_${secret}`;
43	
44	  await db.apiToken.create({
45	    data: {
46	      userId: user.id,
47	      name,
48	      prefix,
49	      tokenHash: hashToken(fullToken),
50	      scopes,
51	      expiresAt,
52	    },
53	  });
54	  await db.auditLog.create({ data: { userId: user.id, action: "user.api_token_created", detail: name } });
55	  revalidatePath("/dashboard/settings");
56	  return { token: fullToken, name };
57	}
58	
59	/** Revoke a token owned by the current user. */
60	export async function revokeApiToken(tokenId: string): Promise<void> {
61	  const user = await requireUser();
62	  await db.apiToken.updateMany({
63	    where: { id: tokenId, userId: user.id },
64	    data: { revoked: true },
65	  });
66	  await db.auditLog.create({ data: { userId: user.id, action: "user.api_token_revoked" } });
67	  revalidatePath("/dashboard/settings");
68	}
