214	/**
215	 * Run arbitrary SQL scoped to one of the account's databases. The SQL runs through
216	 * the mysql2 protocol driver over an SSH-forwarded channel to the node's localhost
217	 * MySQL (never a `mysql` CLI, never a shell), executed as the scoped manager user —
218	 * MySQL's grant is the hard isolation boundary, and there is no CLI meta-command
219	 * interpreter to abuse. Owner-or-admin + not-impersonating + rate-limited.
220	 */
221	export async function dbmgrRunSql(accountId: string, dbName: string, sql: string): Promise<DbMgrResult> {
222	  const empty: DbMgrResult = { columns: [], rows: [], truncated: false, error: null, elapsedMs: 0 };
223	  const ctx = await loadOwned(accountId);
224	  if ("error" in ctx) return { ...empty, error: ctx.error ?? null };
225	  await assertNotImpersonating();
226	  const { user } = ctx;
227	  if (!(await assertOwnedDatabase(accountId, dbName))) return { ...empty, error: "Unknown database." };
228	  const text = String(sql ?? "").trim();
229	  if (!text) return { ...empty, error: "Enter a SQL statement." };
230	  if (Buffer.byteLength(text, "utf8") > MAX_SQL_BYTES) return { ...empty, error: "That query is too large." };
231	  if (!rlOk(user.id, accountId)) return { ...empty, error: "Too many requests — slow down a moment." };
232	
233	  if (SANDBOX) return sandboxResult(text);
234	  const target = dbTargetFor(ctx.a);
235	  if (!target) return { ...empty, error: "The database manager is still being prepared." };
236	  const res: QueryResult = await runScopedSql(target, dbName, text);
237	  if (res.error) return { ...res, error: res.error };
238	  return { ...res, ok: res.columns.length === 0 };
239	}
