29	/**
30	 * Least-loaded enabled+online Proxmox node by RAM headroom, steering away from a
31	 * node this instance would push past the CRITICAL capacity threshold when another
32	 * node has room (mirrors lib/order.ts scheduleNode). Never refuses placement for a
33	 * capacity warning — the node-capacity alert owns that signal; it only prefers a
34	 * roomier node when one exists.
35	 */
36	async function scheduleNode(planRamMB: number): Promise<string | null> {
37	  const nodes = await db.node.findMany({ where: { enabled: true, status: "ONLINE" } });
38	  if (nodes.length === 0) return null;
39	  const loads = await Promise.all(
40	    nodes.map(async (n) => {
41	      const agg = await db.server.findMany({
42	        where: { nodeId: n.id, status: { notIn: ["DELETING"] } },
43	        select: { plan: { select: { ramMB: true } } },
44	      });
45	      const used = agg.reduce((s, r) => s + r.plan.ramMB, 0);
46	      const projectedPct = n.capacityRamMB > 0 ? ((used + planRamMB) / n.capacityRamMB) * 100 : 100;
47	      return { id: n.id, free: n.capacityRamMB - used, projectedPct };
48	    }),
49	  );
50	  const { critPct } = await nodeThresholds();
51	  const roomy = loads.filter((l) => l.projectedPct < critPct);
52	  const pool = roomy.length > 0 ? roomy : loads;
53	  pool.sort((a, b) => b.free - a.free);
54	  return pool[0].id;
55	}
