57	/**
58	 * Order a managed Nextcloud (NxCloud) instance.
59	 *
60	 * MONEY SAFETY — this mirrors the audited VPS/hosting order discipline:
61	 *   - no spending while impersonating; verified email required;
62	 *   - the wallet is charged the FULL displayed monthly price (NO first-month-free —
63	 *     that promo is shared-hosting only), in the SAME transaction that creates the
64	 *     records, so a rolled-back charge leaves no instance and no invoice;
65	 *   - the amount charged is exactly `plan.priceCents`, which is also what the
66	 *     backing Server renews at (its `serverPlan.priceCents` is seeded equal), so
67	 *     displayed === charged === renewed.
68	 *
69	 * The instance is backed by a real `Server`, created here with a PROVISION job.
70	 * The worker clones/sizes the VM and bakes in the Nextcloud install (worker/nxcloud.ts);
71	 * the instance flips to ACTIVE once it verifies serving.
72	 */
73	export async function orderNxCloud(planId: string, subdomainRaw: string, termMonthsRaw?: number): Promise<NxCloudResult> {
74	  const user = await requireUser();
75	  await assertNotImpersonating();
76	
77	  // Ordering gate. NxCloud is visible product-wide, but provisioning must not open
78	  // until the *.nxcloud.nxeon.cloud wildcard DNS exists (Caddy auto-TLS depends on
79	  // it) and the provisioning path has passed a security review. Until the owner
80	  // flips `nxcloud_ordering_enabled`, refuse before touching the wallet. This is a
81	  // pure gate — it changes no price and no money-flow logic below.
82	  if (!(await getSettingBool("nxcloud_ordering_enabled", false))) {
83	    return { error: "NxCloud isn’t open for orders yet — join the waitlist and we’ll let you know the moment it launches." };
84	  }
85	
86	  const unverified = await emailVerificationError(user);
87	  if (unverified) return { error: unverified };
88	
89	  const subdomain = normalizeSubdomain(subdomainRaw);
90	  if (!subdomain) return { error: "Choose a subdomain for your cloud." };
91	  if (!isValidSubdomainLabel(subdomain)) {
92	    return { error: "Subdomain: 3–32 lowercase letters, digits or hyphens (not a reserved word)." };
93	  }
94	
95	  const plan = await db.nxCloudPlan.findUnique({ where: { id: planId }, include: { serverPlan: true } });
96	  if (!plan || !plan.active) return { error: "That NxCloud plan isn’t available." };
97	  if (!plan.serverPlan) return { error: "This plan isn’t fully configured yet — please contact support." };
98	
99	  // The Nextcloud OS image the VM clones from (seeded by prisma/seed-nxcloud.ts).
100	  const osTemplate = await db.osTemplate.findUnique({ where: { slug: "nextcloud" } });
101	  if (!osTemplate) return { error: "NxCloud isn’t available yet — the Nextcloud image hasn’t been seeded." };
102	
103	  // Subdomain is globally unique across all customers (it's a public hostname).
104	  const taken = await db.nxCloudInstance.findFirst({
105	    where: { subdomain, status: { in: [...LIVE_STATES] } },
106	    select: { id: true, userId: true },
107	  });
108	  if (taken) {
109	    return {
110	      error:
111	        taken.userId === user.id
112	          ? "You already have a cloud with that subdomain."
113	          : "That subdomain is taken — try another.",
114	    };
115	  }
116	
117	  // Billing term (Monthly / Annual). NxCloud billing rides the backing Server, so
118	  // the term + frozen annual rate are stamped on that Server and the audited VPS
119	  // renewal sweep (worker/billing.ts) renews it at `termPriceCents(serverPlan price,
120	  // termMonths, frozen annual)`. `plan.priceCents` is seeded equal to
121	  // `serverPlan.priceCents`, so displayed === charged === renewed. The term charge
122	  // is the plan's monthly price over the term at the annual rate.
123	  const term = normalizeProductTerm(termMonthsRaw);
124	  const annualPct = await annualDiscountPct();
125	  const chargeCents = termPriceCents(plan.priceCents, term, annualPct);
126	  if (user.balanceCents < chargeCents) return { error: "Insufficient balance. Top up your wallet first." };
127	
128	  const nodeId = await scheduleNode(plan.serverPlan.ramMB);
129	  const zone = (await getSetting("nxcloud_zone", NXCLOUD_DEFAULT_ZONE)).trim() || NXCLOUD_DEFAULT_ZONE;
130	  const fqdn = nxcloudFqdn(subdomain, zone);
131	  const effMonthly = term > 1 ? Math.round(chargeCents / term) : 0;
132	  const termLabel = term > 1 ? `${vpsTerm(term).label} ($${(effMonthly / 100).toFixed(2)}/mo)` : vpsTerm(term).label;
133	
134	  let instanceId = "";
135	  try {
136	    await db.$transaction(async (tx) => {
137	      await debitWallet(tx, user.id, chargeCents);
138	      await tx.walletTransaction.create({
139	        data: {
140	          userId: user.id,
141	          amountCents: -chargeCents,
142	          description: `NxCloud: ${plan.name} (${fqdn}) — ${termLabel}`,
143	        },
144	      });
145	      await tx.invoice.create({
146	        data: invoiceCreateData({
147	          userId: user.id,
148	          description: `NxCloud: ${plan.name} (${fqdn}) — ${termLabel}`,
149	          status: "PAID",
150	          period: { start: new Date(), end: addMonths(new Date(), term) },
151	          lineItems: [
152	            { description: `${plan.name} — managed Nextcloud (${fqdn}) — ${termLabel}`, qty: 1, unitCents: chargeCents, amountCents: chargeCents },
153	          ],
154	        }),
155	      });
156	      // The backing VM. A normal Server — it renews / duns / suspends / monitors
157	      // through the exact same audited machinery as a VPS. VM snapshot backups are
158	      // ON by default (data-loss safety, spec §6); a public IP is requested so the
159	      // instance is reachable by hostname for auto-TLS.
160	      const server = await tx.server.create({
161	        // Cast: the symlinked prod Prisma client's types predate `annualDiscountPct`
162	        // on Server until regenerated at deploy (see lib/order.ts's Server create).
163	        data: {
164	          name: subdomain,
165	          hostname: subdomain,
166	          userId: user.id,
167	          planId: plan.serverPlanId,
168	          osTemplateId: osTemplate.id,
169	          nodeId,
170	          autoBackup: true,
171	          backupIntervalHours: 24,
172	          // The customer's chosen term (Monthly / Annual). The VPS renewal sweep reads
173	          // this + annualDiscountPct off the Server and renews at the sold rate.
174	          termMonths: term,
175	          // Sold at full price — 0% off — so no later proration can claw a discount
176	          // that was never given (see Server.termPromoPercent).
177	          termPromoPercent: 0,
178	          // The annual rate frozen at sale, so the renewal bills the SAME price the
179	          // order charged even if the admin retunes the discount afterwards.
180	          annualDiscountPct: annualPct,
181	          wantsDedicatedIp: true,
182	          isFree: false,
183	          expiresAt: addMonths(new Date(), term),
184	        } as Prisma.ServerUncheckedCreateInput,
185	      });
186	      const inst = await tx.nxCloudInstance.create({
187	        data: {
188	          userId: user.id,
189	          planId: plan.id,
190	          serverId: server.id,
191	          subdomain,
192	          status: "PENDING",
193	          adminUser: "admin",
194	          storageQuotaMB: plan.storageGB * 1024,
195	        },
196	      });
197	      instanceId = inst.id;
198	      await tx.job.create({ data: { type: "PROVISION", serverId: server.id } });
199	    });
200	  } catch (e) {
201	    if (e instanceof InsufficientBalanceError) return { error: "Insufficient balance. Top up your wallet first." };
202	    return { error: "Couldn’t place the order. Your wallet was not charged — try again." };
203	  }
204	
205	  await db.auditLog
206	    .create({ data: { userId: user.id, action: "nxcloud.order", detail: `${plan.name} · ${fqdn}` } })
207	    .catch(() => {});
208	  revalidatePath("/dashboard/nxcloud");
209	  return { ok: true, instanceId };
210	}
