298	export async function retryNxcloud(instanceId: string): Promise<NxCloudResult> {
299	  const user = await requireUser();
300	  const inst = await db.nxCloudInstance.findUnique({
301	    where: { id: instanceId },
302	    select: { userId: true, status: true, serverId: true },
303	  });
304	  if (!inst) return { error: "Not found." };
305	  if (inst.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
306	  if (inst.status !== "FAILED") return { error: "This cloud isn’t in a failed state." };
307	  if (!inst.serverId) return { error: "No backing server to retry — please contact support." };
308	  // Don't double-enqueue if a job is already in flight on the backing server.
309	  const inflight = await db.job.count({
310	    where: { serverId: inst.serverId, status: { in: ["QUEUED", "RUNNING"] } },
311	  });
312	  if (inflight > 0) return { error: "A setup task is already running on this cloud." };
313	
314	  await db.$transaction([
315	    db.nxCloudInstance.update({ where: { id: instanceId }, data: { status: "PENDING", error: null } }),
316	    db.server.update({ where: { id: inst.serverId }, data: { status: "PROVISIONING", provisionError: null } }),
317	    db.job.create({ data: { type: "PROVISION", serverId: inst.serverId } }),
318	  ]);
319	  await db.auditLog
320	    .create({ data: { userId: user.id, action: "nxcloud.retry_provision", detail: instanceId } })
321	    .catch(() => {});
322	  revalidatePath("/dashboard/nxcloud");
323	  return { ok: true };
324	}
