516	export async function listHostingUpgradePlans(accountId: string): Promise<{ currentPlanName?: string; plans?: UpgradePlanView[]; error?: string }> {
517	  const user = await requireUser();
518	  const a = await db.hostingAccount.findUnique({ where: { id: accountId }, include: { plan: true } });
519	  if (!a) return { error: "Account not found." };
520	  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
521	  const cur = a.plan;
522	  const all = await db.hostingPlan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } });
523	  const plans = all
524	    .filter((p) => p.id !== cur.id && p.priceCents >= cur.priceCents && p.diskGB >= cur.diskGB && (p.priceCents > cur.priceCents || p.diskGB > cur.diskGB))
525	    .map((p) => ({
526	      id: p.id, name: p.name, priceCents: p.priceCents, diskGB: p.diskGB, maxSites: p.maxSites,
527	      maxDatabases: p.maxDatabases, bandwidthTB: p.bandwidthTB, tagline: p.tagline,
