533	/**
534	 * Move a hosting account UP to a larger plan. Same purchase discipline as
535	 * orderHostingAccount: no spending while impersonating, wallet charge in the same
536	 * tx that mutates the account.
537	 *
538	 * Billing choice (kept simple + honest): we charge the FULL per-term price
539	 * DIFFERENCE (new − current) now, and leave the renewal date unchanged; future
540	 * terms bill at the new plan price. No mid-term proration or refunds — that keeps
541	 * the flow one debit and never owes the customer money back. The customer sees the
542	 * exact delta before confirming. Only UP is allowed (a downgrade would need a
543	 * refund path we don't have).
544	 */
545	export async function upgradeHostingPlan(accountId: string, newPlanId: string): Promise<HostingResult> {
546	  const user = await requireUser();
547	  await assertNotImpersonating();
548	  const a = await db.hostingAccount.findUnique({ where: { id: accountId }, include: { plan: true } });
549	  if (!a) return { error: "Account not found." };
550	  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
551	  if (a.status !== "ACTIVE") return { error: "The account is still being set up." };
552	  const newPlan = await db.hostingPlan.findUnique({ where: { id: newPlanId } });
553	  if (!newPlan || !newPlan.active) return { error: "That plan isn’t available." };
554	  if (newPlan.id === a.planId) return { error: "You’re already on this plan." };
555	  const cur = a.plan;
556	  // Up-only guard (re-checked server-side; never trust the client's picker).
557	  if (newPlan.priceCents < cur.priceCents || newPlan.diskGB < cur.diskGB) {
558	    return { error: "You can only move to a larger plan." };
559	  }
560	  const limits = planLimits(newPlan);
561	  const chargeCents = Math.max(0, newPlan.priceCents - cur.priceCents);
562	  if (user.balanceCents < chargeCents) return { error: "Insufficient balance. Top up your wallet first." };
563	
564	  try {
565	    await db.$transaction(async (tx) => {
566	      if (chargeCents > 0) {
567	        await debitWallet(tx, user.id, chargeCents);
568	        await tx.walletTransaction.create({
569	          data: { userId: user.id, amountCents: -chargeCents, description: `Web Hosting upgrade: ${cur.name} → ${newPlan.name} for ${a.primaryDomain}` },
570	        });
571	      }
572	      // Snapshot the new plan's limits onto the account (same as orderHostingAccount
573	      // does at creation), so a later plan edit can't silently re-quota this account.
574	      // phpVersion is left as-is: an upgrade only widens the allowed set.
575	      await tx.hostingAccount.update({
576	        where: { id: a.id },
577	        data: { planId: newPlan.id, diskQuotaMB: limits.diskGB * 1024, maxSites: limits.maxSites, maxDatabases: limits.maxDatabases },
578	      });
579	      // Enact the node-level change (raise disk quota + rewrite FPM pool).
580	      await tx.hostingTask.create({ data: { accountId: a.id, kind: "APPLY_PLAN_LIMITS" } });
581	    });
582	  } catch (e) {
583	    if (e instanceof InsufficientBalanceError) return { error: "Insufficient balance. Top up your wallet first." };
584	    return { error: "Couldn’t upgrade the plan. Your wallet was not charged — try again." };
585	  }
586	
587	  await db.auditLog.create({ data: { userId: user.id, action: "hosting.upgrade", detail: `${cur.name} → ${newPlan.name} · ${a.primaryDomain}` } }).catch(() => {});
588	  revalidatePath(`/dashboard/hosting/${accountId}`);
589	  return { ok: true };
590	}
