672	// ---------- Subdomains + addon domains + cron (cPanel-class site mgmt) -------
673	// Every value that reaches the node shell is validated here (isValidUnixUsername
674	// / isValidHostingDomain / isValidSubdomainLabel / cron validators) AND re-checked
675	// in the worker. Caps are enforced inside a Serializable transaction so concurrent
676	// creates cannot both read a stale count and blow past the plan (same discipline
677	// as createHostingDatabase). The task is queued in the SAME tx as the row create.
678	
679	const SITE_STATES = ["PENDING", "ACTIVE"] as const;
