682	/** Owner (or admin) + ACTIVE account, returning the fields the site actions need. */
683	async function ownedSiteAccount(id: string) {
684	  const user = await requireUser();
685	  // Impersonating admins must not create/destroy customer resources — cron is
686	  // arbitrary command execution as the customer's unix user; subdomains/addons
687	  // mint live vhosts. Matches createHostingAccount/createHostingDatabase (audit MED-3).
688	  await assertNotImpersonating();
689	  const a = await db.hostingAccount.findUnique({
690	    where: { id },
691	    select: { id: true, userId: true, status: true, username: true, primaryDomain: true, maxSites: true },
692	  });
693	  if (!a) return { error: "Account not found." as const };
694	  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." as const };
695	  if (a.status !== "ACTIVE") return { error: "The account is still being set up." as const };
696	  return { user, a };
