820	  const name = normalizeHostingDomain(domain);
821	  if (!name || !isValidHostingDomain(name)) return { error: "Enter a valid domain (e.g. example.com)." };
822	  if (name === a.primaryDomain) return { error: "That’s already your primary domain." };
823	  // Cross-tenant uniqueness across ALL three hostname tables — a shared vhost keys
824	  // on server_name, so an addon must not shadow anyone's primary, subdomain, or
825	  // addon (audit HIGH-1: this used to omit HostingSubdomain.fqdn).
826	  if (await isHostnameClaimed(name)) {
827	    return { error: "That domain is already hosted on Nxeon. If it’s yours, contact support to move it across." };
828	  }
829	  const { docroot } = addonDomainPaths(a.username, name);
830	  try {
831	    await db.$transaction(async (tx) => {
832	      const subs = await tx.hostingSubdomain.count({ where: { accountId: a.id, status: { in: [...SITE_STATES] } } });
833	      const addons = await tx.hostingAddonDomain.count({ where: { accountId: a.id, status: { in: [...SITE_STATES] } } });
834	      if (subs + addons >= a.maxSites) throw new Error("CAP");
835	      const addon = await tx.hostingAddonDomain.create({ data: { accountId: a.id, domain: name, docroot, status: "PENDING" } });
836	      // Atomic cross-tenant claim in the SAME tx: the UNIQUE(hostname) is the
837	      // authoritative guard against another tenant committing this same
838	      // server_name as their primary/subdomain/addon between our check and commit.
839	      await tx.hostingHostnameClaim.create({ data: { hostname: normalizeClaimHostname(name), accountId: a.id, kind: "ADDON" } });
840	      await tx.hostingTask.create({ data: { accountId: a.id, kind: "CREATE_ADDON_DOMAIN", payload: JSON.stringify({ addonId: addon.id }) } });
841	    }, { isolationLevel: "Serializable" });
842	  } catch (e) {
843	    if (e instanceof Error && e.message === "CAP") return { error: siteCapMessage(a.maxSites) };
844	    if (isUniqueViolation(e)) return { error: "That domain is already hosted on Nxeon. If it’s yours, contact support to move it across." };
845	    return { error: "That domain is already added, or the request raced — try again." };
846	  }
847	  revalidatePath(`/dashboard/hosting/${accountId}`);
848	  return { ok: true };
849	}
